import json


def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        for key in set(a.keys()) | set(b.keys()):
            if key in a and key in b:
                result[key] = deep_merge(a[key], b[key])
            elif key in a:
                result[key] = a[key]
            else:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        seen = []
        for item in a + b:
            if item not in seen:
                seen.append(item)
        return seen
    else:
        return b


def main():
    path_a = "<tmp>"
    path_b = "<tmp>"

    with open(path_a, "r") as f:
        a = json.load(f)
    with open(path_b, "r") as f:
