let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }

let dataLines = Array(lines.dropFirst())

var deptSalaries: [String: [Double]] = [:]
var names: [String] = []
var salaries: [Double] = []
var deptList: [String] = []

for line in dataLines {
    let cols = line.components(separatedBy: ",")
    guard cols.count >= 6 else { continue }
    let name = cols[1].trimmingCharacters(in: .whitespaces)
    let dept = cols[2].trimmingCharacters(in: .whitespaces)
    let salary = Double(cols[3].trimmingCharacters(in: .whitespaces)) ?? 0

    names.append(name)
    salaries.append(salary)
    deptList.append(dept)

    if deptSalaries[dept] == nil {
        deptSalaries[dept] = []
    }
    deptSalaries[dept]!.append(salary)
}

func formatWithCommas(_ value: Double, decimals: Int) -> String {
    let formatter = NumberFormatter()
    formatter.locale = Locale(identifier: "en_US")
    formatter.numberStyle = .decimal
    formatter.minimumFractionDigits = decimals
    formatter.maximumFractionDigits = decimals
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.usesGroupingSeparator = true
    return formatter.string(from: NSNumber(value: value)) ?? ""
}

print("=== Salary Report ===")
print()
print("Average Salary by Department:")
let sortedDepts = deptSalaries.keys.sorted()
for dept in sortedDepts {
    let sals = deptSalaries[dept]!
    let avg = sals.reduce(0, +) / Double(sals.count)
    print("  \(dept): $\(formatWithCommas(avg, decimals: 2))")
}
print()

var maxIdx = 0
for i in 1..<salaries.count {
    if salaries[i] > salaries[maxIdx] {
        maxIdx = i
    }
}
let maxSalaryInt = Int(salaries[maxIdx])
print("Highest Paid: \(names[maxIdx]) ($\(formatWithCommas(Double(maxSalaryInt), decimals: 0)))")
print()

var deptCounts: [String: Int] = [:]
for d in deptList {
    deptCounts[d, default: 0] += 1
}
print("Departments with >2 employees:")
let filteredDepts = deptCounts.filter { $0.value > 2 }.keys.sorted()
for dept in filteredDepts {
    print("  \(dept) (\(deptCounts[dept]!) employees)")
}
print()

let totalInt = Int(salaries.reduce(0, +))
print("Total Budget: $\(formatWithCommas(Double(totalInt), decimals: 0))")

