import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";

        List<String> lines = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(path));
        String line;
        while ((line = br.readLine()) != null) {
            lines.add(line);
        }
        br.close();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        for (int i = 1; i < lines.size(); i++) {
            String l = lines.get(i).trim();
            if (l.isEmpty()) continue;
            String[] parts = l.split(",");
            if (parts.length < 6) continue;

            String name = parts[1].trim();
            String department = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim().replace(",", ""));

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCount.merge(department, 1, Integer::sum);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            System.out.printf("  %s: $%,.2f%n", entry.getKey(), avg);
        }
        System.out.println();
        System.out.printf("Highest Paid: %s ($%,d)%n", highestName, Math.round(highestSalary));
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }
        System.out.println();
        System.out.printf("Total Budget: $%,d%n", Math.round(totalBudget));
    }
}

