import * as fs from 'fs';

const csvPath = '<tmp>';

const content = fs.readFileSync(csvPath, 'utf-8');
const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');

const employees = lines.slice(1).map(line => {
  const cols = line.split(',').map(c => c.trim());
  return {
    employee_id: cols[0],
    name: cols[1],
    department: cols[2],
    salary: parseFloat(cols[3]),
    start_date: cols[4],
    rating: cols[5]
  };
});

function formatMoney(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const parts = fixed.split('.');
  let intPart = parts[0];
  const decPart = parts[1];

  const negative = intPart.startsWith('-');
  if (negative) intPart = intPart.slice(1);

  let result = '';
  for (let i = 0; i < intPart.length; i++) {
    if (i > 0 && (intPart.length - i) % 3 === 0) {
      result += ',';
    }
    result += intPart[i];
  }
  if (negative) result = '-' + result;

  if (decimals > 0) {
    result += '.' + decPart;
  }
  return result;
}

const deptSalaries: Record<string, number[]> = {};
for (const emp of employees) {
  if (!deptSalaries[emp.department]) {
    deptSalaries[emp.department] = [];
  }
  deptSalaries[emp.department].push(emp.salary);
}

const sortedDepts = Object.keys(deptSalaries).sort();

let highestEmp = employees[0];
for (const emp of employees) {
  if (emp.salary > highestEmp.salary) {
    highestEmp = emp;
  }
}

const deptCounts: Record<string, number> = {};
for (const emp of employees) {
  deptCounts[emp.department] = (deptCounts[emp.department] || 0) + 1;
}

const deptsWithMoreThan2 = Object.keys(deptCounts).filter(d => deptCounts[d] > 2).sort();

const totalBudget = employees.reduce((sum, emp) => sum + emp.salary, 0);

const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
for (const dept of sortedDepts) {
  const salaries = deptSalaries[dept];
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  out.push(`  ${dept}: $${formatMoney(avg, 2)}`);
}
out.push('');
out.push(`Highest Paid: ${highestEmp.name} ($${formatMoney(Math.round(highestEmp.salary), 0)})`);
out.push('');
out.push('Departments with >2 employees:');
for (const dept of deptsWithMoreThan2) {
  out.push(`  ${dept} (${deptCounts[dept]} employees)`);
}
out.push('');
out.push(`Total Budget: $${formatMoney(Math.round(totalBudget), 0)}`);

process.stdout.write(out.join('\n') + '\n');

