use std::collections::HashMap;
use std::fs;

fn format_number_with_commas(n: f64, decimals: usize) -> String {
    let formatted = format!("{:.*}", decimals, n);
    let (int_part, dec_part) = if formatted.contains('.') {
        let parts: Vec<&str> = formatted.splitn(2, '.').collect();
        (parts[0].to_string(), parts.get(1).copied().unwrap_or("").to_string())
    } else {
        (formatted.clone(), String::new())
    };

    let is_negative = int_part.starts_with('-');
    let int_abs = if is_negative { &int_part[1..] } else { &int_part };

    let mut result = String::new();
    let chars: Vec<char> = int_abs.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }

    if is_negative {
        result = format!("-{}", result);
    }

    if decimals > 0 {
        format!("{}.{}", result, dec_part)
    } else {
        result
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_name = String::new();
    let mut highest_salary = f64::MIN;
    let mut total_budget = 0.0f64;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
