import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '<tmp>';
    const data = fs.readFileSync(filePath, 'utf-8');
    const graph: Graph = JSON.parse(data);

    // Build adjacency list (undirected)
    const adj: Map<string, Map<string, number>> = new Map();
    for (const node of graph.nodes) {
        adj.set(node, new Map());
    }
    for (const edge of graph.edges) {
        if (!adj.has(edge.from)) adj.set(edge.from, new Map());
        if (!adj.has(edge.to)) adj.set(edge.to, new Map());
        adj.get(edge.from)!.set(edge.to, edge.weight);
        adj.get(edge.to)!.set(edge.from, edge.weight);
    }

    // Dijkstra's algorithm
    const source = "A";
    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of graph.nodes) {
        dist.set(node, Infinity);
    }
    dist.set(source, 0);

    while (visited.size < graph.nodes.length) {
        let minNode: string | null = null;
        let minDist = Infinity;
        for (const node of graph.nodes) {
            if (!visited.has(node) && (dist.get(node) ?? Infinity) < minDist) {
                minDist = dist.get(node)!;
                minNode = node;
            }
        }

        if (minNode === null) break;

        visited.add(minNode);

        const neighbors = adj.get(minNode);
        if (neighbors) {
            for (const [neighbor, weight] of neighbors) {
                if (!visited.has(neighbor)) {
                    const newDist = dist.get(minNode)! + weight;
                    if (newDist < (dist.get(neighbor) ?? Infinity)) {
                        dist.set(neighbor, newDist);
                    }
                }
            }
        }
    }

    // Output
    const sortedNodes = [...graph.nodes].sort();
    let output = "=== Shortest Paths from A ===\n";
    output += "\n";
    for (const node of sortedNodes) {
        const d = dist.get(node)!;
        const display = d === Infinity ? "unreachable" : String(d);
        output += `A -> ${node}: ${display}\n`;
    }

    process.stdout.write(output);
}

main();

