        List<String> nodes = parseStringArray(json, "nodes");
        List<String[]> edges = parseEdges(json);

        Map<String, List<String[]>> adj = new HashMap<>();
        for (String n : nodes) {
            adj.put(n, new ArrayList<>());
        }
        for (String[] e : edges) {
            adj.get(e[0]).add(new String[]{e[1], e[2]});
            adj.get(e[1]).add(new String[]{e[0], e[2]});
        }

        Map<String, Double> dist = new HashMap<>();
        for (String n : nodes) {
            dist.put(n, Double.POSITIVE_INFINITY);
        }
        dist.put("A", 0.0);

        PriorityQueue<Object[]> pq = new PriorityQueue<>((a, b) -> Double.compare((Double) a[0], (Double) b[0]));
        pq.add(new Object[]{0.0, "A"});

        while (!pq.isEmpty()) {
            Object[] curr = pq.poll();
            double d = (Double) curr[0];
            String node = (String) curr[1];

            if (d > dist.get(node)) continue;

            List<String[]> neighbors = adj.get(node);
