            for (String[] nb : neighbors) {
                String nNode = nb[0];
                double w = Double.parseDouble(nb[1]);
                double newDist = d + w;
                if (newDist < dist.get(nNode)) {
                    dist.put(nNode, newDist);
                    pq.add(new Object[]{newDist, nNode});
                }
            }
        }

