                    }
                    result.push('\n');
                }
                result.push_str(&pad);
                result.push('}');
                result
            }
        }
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (a, b) {
        (Json::Object(mut obj_a), Json::Object(obj_b)) => {
            for (key, val_b) in obj_b {
                match obj_a.remove(&key) {
                    Some(val_a) => {
