    int n = obj->pair_count;
    char **tmp_keys = (char **)malloc(n * sizeof(char *));
    JsonValue **tmp_vals = (JsonValue **)malloc(n * sizeof(JsonValue *));
    for (int i = 0; i < n; i++) {
        tmp_keys[i] = obj->keys[i];
        tmp_vals[i] = obj->values[i];
