        if (isdigit((unsigned char)c) || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E')
            p->pos++;
        else
            break;
    }
    long nlen = p->pos - start;
    char *numstr = (char *)malloc(nlen + 1);
    memcpy(numstr, p->text + start, nlen);
    numstr[nlen] = '\0';
    JsonValue *v = new_value(JSON_NUMBER);
    v->number = strtod(numstr, NULL);
    v->num_str = numstr;
    return v;
}

static JsonValue *parse_value(Parser *p);

static JsonValue *parse_object(Parser *p) {
    p->pos++; /* skip '{' */
    JsonValue *obj = new_value(JSON_OBJECT);
    obj->keys = NULL;
    obj->values = NULL;
    obj->pair_count = 0;
    obj->pair_cap = 0;

    skip_ws(p);
    if (p->pos < p->len && p->text[p->pos] == '}') {
        p->pos++;
        return obj;
    }

    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        if (!key) break;
        skip_ws(p);
        if (p->pos < p->len && p->text[p->pos] == ':') p->pos++;
        skip_ws(p);
        JsonValue *val = parse_value(p);

        if (obj->pair_count >= obj->pair_cap) {
            obj->pair_cap = obj->pair_cap ? obj->pair_cap * 2 : 8;
            obj->keys = (char **)realloc(obj->keys, obj->pair_cap * sizeof(char *));
            obj->values = (JsonValue **)realloc(obj->values, obj->pair_cap * sizeof(JsonValue *));
        }
        /* If duplicate key, overwrite */
        int found = -1;
        for (int i = 0; i < obj->pair_count; i++) {
            if (strcmp(obj->keys[i], key) == 0) { found = i; break; }
        }
        if (found >= 0) {
            free(obj->keys[found]);
            obj->keys[found] = key;
            obj->values[found] = val;
        } else {
            obj->keys[obj->pair_count] = key;
            obj->values[obj->pair_count] = val;
            obj->pair_count++;
        }

        skip_ws(p);
        if (p->pos < p->len && p->text[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->text[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static JsonValue *parse_array(Parser *p) {
    p->pos++; /* skip '[' */
    JsonValue *arr = new_value(JSON_ARRAY);
    arr->items = NULL;
    arr->item_count = 0;
    arr->item_cap = 0;

    skip_ws(p);
    if (p->pos < p->len && p->text[p->pos] == ']') {
        p->pos++;
        return arr;
    }

    while (1) {
        skip_ws(p);
        JsonValue *val = parse_value(p);
        if (!val) break;

        if (arr->item_count >= arr->item_cap) {
            arr->item_cap = arr->item_cap ? arr->item_cap * 2 : 8;
            arr->items = (JsonValue **)realloc(arr->items, arr->item_cap * sizeof(JsonValue *));
        }
        arr->items[arr->item_count++] = val;

        skip_ws(p);
        if (p->pos < p->len && p->text[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->text[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return NULL;
    char c = p->text[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        char *s = parse_string_raw(p);
        JsonValue *v = new_value(JSON_STRING);
        v->string = s;
        return v;
    }
    if (c == 't' && p->pos + 3 < p->len && memcmp(p->text + p->pos, "true", 4) == 0) {
        p->pos += 4;
        JsonValue *v = new_value(JSON_BOOL);
        v->boolean = 1;
        return v;
    }
    if (c == 'f' && p->pos + 4 < p->len && memcmp(p->text + p->pos, "false", 5) == 0) {
        p->pos += 5;
        JsonValue *v = new_value(JSON_BOOL);
        v->boolean = 0;
        return v;
    }
    if (c == 'n' && p->pos + 3 < p->len && memcmp(p->text + p->pos, "null", 4) == 0) {
        p->pos += 4;
        return new_value(JSON_NULL);
    }
    if (c == '-' || isdigit((unsigned char)c)) {
        return parse_number(p);
    }
    /* fallback: skip */
    p->pos++;
    return NULL;
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (sz > 0) {
        size_t rd = fread(buf, 1, sz, f);
        (void)rd;
    }
    buf[sz] = '\0';
    fclose(f);
    return buf;
}

static int json_equal(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return a->string && b->string && strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++) {
                if (!json_equal(a->items[i], b->items[i])) return 0;
            }
            return 1;
        case JSON_OBJECT:
            if (a->pair_count != b->pair_count) return 0;
            for (int i = 0; i < a->pair_count; i++) {
                int found = -1;
                for (int j = 0; j < b->pair_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) { found = j; break; }
                }
                if (found < 0) return 0;
                if (!json_equal(a->values[i], b->values[found])) return 0;
            }
            return 1;
    }
    return 0;
}

static int array_contains(JsonValue *arr, JsonValue *item) {
    for (int i = 0; i < arr->item_count; i++) {
        if (json_equal(arr->items[i], item)) return 1;
    }
    return 0;
}

static JsonValue *deep_merge(JsonValue *a, JsonValue *b) {
    /* Both objects: merge recursively */
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = new_value(JSON_OBJECT);
        /* Start with all of A's keys */
        for (int i = 0; i < a->pair_count; i++) {
            if (result->pair_count >= result->pair_cap) {
                result->pair_cap = result->pair_cap ? result->pair_cap * 2 : 16;
                result->keys = (char **)realloc(result->keys, result->pair_cap * sizeof(char *));
                result->values = (JsonValue **)realloc(result->values, result->pair_cap * sizeof(JsonValue *));
            }
            result->keys[result->pair_count] = strdup(a->keys[i]);
            result->values[result->pair_count] = a->values[i];
            result->pair_count++;
        }
        /* For each key in B, merge or add */
        for (int i = 0; i < b->pair_count; i++) {
            int found = -1;
            for (int j = 0; j < result->pair_count; j++) {
                if (strcmp(result->keys[j], b->keys[i]) == 0) { found = j; break; }
            }
            if (found >= 0) {
                result->values[found] = deep_merge(result->values[found], b->values[i]);
            } else {
                if (result->pair_count >= result->pair_cap) {
                    result->pair_cap = result->pair_cap ? result->pair_cap * 2 : 16;
                    result->keys = (char **)realloc(result->keys, result->pair_cap * sizeof(char *));
                    result->values = (JsonValue **)realloc(result->values, result->pair_cap * sizeof(JsonValue *));
                }
                result->keys[result->pair_count] = strdup(b->keys[i]);
                result->values[result->pair_count] = b->values[i];
                result->pair_count++;
            }
        }
        return result;
    }
    /* Both arrays: concatenate and remove duplicates */
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = new_value(JSON_ARRAY);
        /* Add items from A (dedup within A) */
        for (int i = 0; i < a->item_count; i++) {
            if (!array_contains(result, a->items[i])) {
                if (result->item_count >= result->item_cap) {
                    result->item_cap = result->item_cap ? result->item_cap * 2 : 16;
                    result->items = (JsonValue **)realloc(result->items, result->item_cap * sizeof(JsonValue *));
                }
                result->items[result->item_count++] = a->items[i];
            }
        }
        /* Add items from B (dedup against result) */
        for (int i = 0; i < b->item_count; i++) {
            if (!array_contains(result, b->items[i])) {
                if (result->item_count >= result->item_cap) {
                    result->item_cap = result->item_cap ? result->item_cap * 2 : 16;
                    result->items = (JsonValue **)realloc(result->items, result->item_cap * sizeof(JsonValue *));
                }
                result->items[result->item_count++] = b->items[i];
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return b;
}

/* Sort object keys alphabetically */
static int cmp_keys(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

static void sort_object_keys(JsonValue *obj) {
    if (obj->type != JSON_OBJECT || obj->pair_count <= 1) return;
    /* Sort keys and values together */
    int n = obj->pair_count;
    char **tmp_keys = (char **)malloc(n * sizeof(char *));
    JsonValue **tmp_vals = (JsonValue **)malloc(n * sizeof(JsonValue *));
    for (int i = 0; i < n; i++) {
        tmp_keys[i] = obj->keys[i];
        tmp_vals[i] = obj->values[i];
    }
    /* Simple insertion sort to keep keys and values in sync */
    for (int i = 1; i < n; i++) {
        char *tk = tmp_keys[i];
        JsonValue *tv = tmp_vals[i];
        int j = i - 1;
        while (j >= 0 && strcmp(tmp_keys[j], tk) > 0) {
            tmp_keys[j + 1] = tmp_keys[j];
            tmp_vals[j + 1] = tmp_vals[j];
            j--;
        }
        tmp_keys[j + 1] = tk;
        tmp_vals[j + 1] = tv;
    }
    for (int i = 0; i < n; i++) {
        obj->keys[i] = tmp_keys[i];
        obj->values[i] = tmp_vals[i];
    }
    free(tmp_keys);
    free(tmp_vals);
    /* Recurse into values */
    for (int i = 0; i < obj->pair_count; i++) {
        if (obj->values[i]->type == JSON_OBJECT) sort_object_keys(obj->values[i]);
        else if (obj->values[i]->type == JSON_ARRAY) {
            for (int j = 0; j < obj->values[i]->item_count; j++) {
                if (obj->values[i]->items[j]->type == JSON_OBJECT) sort_object_keys(obj->values[i]->items[j]);
            }
        }
    }
}

static void sort_array_objects(JsonValue *arr) {
    for (int i = 0; i < arr->item_count; i++) {
        if (arr->items[i]->type == JSON_OBJECT) sort_object_keys(arr->items[i]);
        else if (arr->items[i]->type == JSON_ARRAY) sort_array_objects(arr->items[i]);
    }
}

static void sort_all(JsonValue *v) {
    if (v->type == JSON_OBJECT) {
        sort_object_keys(v);
    } else if (v->type == JSON_ARRAY) {
        sort_array_objects(v);
    }
}

static void print_string_escaped(const char *s) {
    fputc('"', stdout);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20) {
                    printf("\\u%04x", c);
                } else {
                    fputc(c, stdout);
                }
        }
    }
    fputc('"', stdout);
}

static void print_number(double d, const char *num_str) {
    if (num_str) {
        /* Check if it's an integer (no ., e, E in the representation) */
        int is_int = 1;
        for (const char *p = num_str; *p; p++) {
            if (*p == '.' || *p == 'e' || *p == 'E') { is_int = 0; break; }
        }
        if (is_int) {
            printf("%s", num_str);
        } else {
            /* Print as-is from the source */
            printf("%s", num_str);
        }
    } else {
        if (d == (long long)d && fabs(d) < 1e15) {
            printf("%lld", (long long)d);
        } else {
            printf("%g", d);
        }
    }
}

static void print_json(JsonValue *v, int indent) {
    if (!v) {
        fputs("null", stdout);
        return;
    }
    switch (v->type) {
        case JSON_NULL:
            fputs("null", stdout);
            break;
        case JSON_BOOL:
            fputs(v->boolean ? "true" : "false", stdout);
            break;
        case JSON_NUMBER:
            print_number(v->number, v->num_str);
            break;
        case JSON_STRING:
            print_string_escaped(v->string ? v->string : "");
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) {
                fputs("[]", stdout);
                break;
            }
            fputs("[\n", stdout);
            for (int i = 0; i < v->item_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_json(v->items[i], indent + 1);
                if (i < v->item_count - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputs("]", stdout);
            break;
        case JSON_OBJECT:
            if (v->pair_count == 0) {
                fputs("{}", stdout);
                break;
            }
            fputs("{\n", stdout);
            for (int i = 0; i < v->pair_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_string_escaped(v->keys[i]);
                fputs(": ", stdout);
                print_json(v->values[i], indent + 1);
                if (i < v->pair_count - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputs("}", stdout);
            break;
    }
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    char *file_a = read_file(path_a);
    char *file_b = read_file(path_b);

    Parser pa, pb;
    parser_init(&pa, file_a);
    parser_init(&pb, file_b);

    JsonValue *a = parse_value(&pa);
    JsonValue *b = parse_value(&pb);

    if (!a || !b) {
        fprintf(stderr, "Failed to parse JSON\n");
        return 1;
    }

    JsonValue *merged = deep_merge(a, b);

    sort_all(merged);

    print_json(merged, 0);
    fputc('\n', stdout);

    return 0;
}
