        }

        for (List<FileInfo> files : extMap.values()) {
            files.sort((a, b) -> a.relPath.compareTo(b.relPath));
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        int totalFiles = 0;
        int totalLines = 0;
        int totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files.size());

            int extLines = 0;
            int extChars = 0;
            for (FileInfo fi : files) {
                extLines += fi.lines;
                extChars += fi.chars;
            }

            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);

            for (FileInfo fi : files) {
                System.out.println("    " + fi.relPath + ": " + fi.lines + " lines, " + fi.chars + " chars");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static void walk(Path dir, Path root, Map<String, List<FileInfo>> extMap, Set<Path> visited) throws IOException {
        Path realDir;
        try {
            realDir = dir.toRealPath();
        } catch (IOException e) {
            return;
        }
        if (!visited.add(realDir)) return;

        File[] files = dir.toFile().listFiles();
        if (files == null) return;

        for (File f : files) {
            Path filePath = dir.resolve(f.getName());

            if (Files.isSymbolicLink(filePath)) {
                continue;
            }

            if (Files.isDirectory(filePath)) {
                walk(filePath, root, extMap, visited);
            } else if (Files.isRegularFile(filePath)) {
                String relPath = root.relativize(filePath).toString().replace(File.separatorChar, '/');

                byte[] bytes = Files.readAllBytes(filePath);
                int chars = bytes.length;

                int lines = 0;
                if (chars > 0) {
                    for (byte b : bytes) {
                        if (b == '\n') lines++;
                    }
                    if (bytes[chars - 1] != '\n') lines++;
                }

                String name = f.getName();
                String ext = "";
                int dotIdx = name.lastIndexOf('.');
                if (dotIdx > 0) {
                    ext = name.substring(dotIdx);
                }

                extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
            }
        }
    }
}
