import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(content: string): number {
  if (content.length === 0) return 0;
  const parts = content.split('\n');
  let lines = parts.length;
  if (content.endsWith('\n')) lines -= 1;
  return lines;
}

function walk(dir: string, root: string, visited: Set<string>, result: Map<string, FileStats[]>): void {
  let realDir: string;
  try {
    realDir = fs.realpathSync(dir);
  } catch {
    return;
  }
  if (visited.has(realDir)) return;
  visited.add(realDir);

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;

    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(root, fullPath).replace(/\\/g, '/');

    if (entry.isDirectory()) {
      walk(fullPath, root, visited, result);
    } else if (entry.isFile()) {
      let chars: number;
      let lines: number;
      try {
        const stats = fs.statSync(fullPath);
        chars = stats.size;
        const content = fs.readFileSync(fullPath, 'utf-8');
        lines = countLines(content);
      } catch {
        continue;
      }

      const ext = path.extname(entry.name);
      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const visited = new Set<string>();
const fileMap = new Map<string, FileStats[]>();
walk(rootDir, rootDir, visited, fileMap);

const sortedExts = Array.from(fileMap.keys()).sort();

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

let output = '=== File Tree Analysis ===\n\n';

for (const ext of sortedExts) {
  const files = fileMap.get(ext)!.sort((a, b) =>
    a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0
  );
  const extLines = files.reduce((s, f) => s + f.lines, 0);
  const extChars = files.reduce((s, f) => s + f.chars, 0);

  output += `Extension: ${ext}\n`;
  output += `  Files: ${files.length}\n`;
  output += `  Total Lines: ${extLines}\n`;
  output += `  Total Characters: ${extChars}\n`;

  for (const f of files) {
    output += `    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`;
  }

  totalFiles += files.length;
  totalLines += extLines;
  totalChars += extChars;
}

output += `\nTotal: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

