func walkDirectory(_ dirPath: String, basePath: String, visited: inout Set<String>) {
    let fm = FileManager.default
    guard let contents = try? fm.contentsOfDirectory(atPath: dirPath) else { return }

    for name in contents {
        let fullPath = dirPath + "/" + name
        let url = URL(fileURLWithPath: fullPath)

        let values = try? url.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey])
        let isSymlink = values?.isSymbolicLink ?? false

        if isSymlink {
            continue
        }

        let isDir = values?.isDirectory ?? false

        if isDir {
            let realPath = (fullPath as NSString).resolvingSymlinksInPath
            if visited.contains(realPath) {
                continue
            }
            visited.insert(realPath)
            walkDirectory(fullPath, basePath: basePath, visited: &visited)
        } else {
            let relativePath = String(fullPath.dropFirst(basePath.count + 1))

            let ext = url.pathExtension
            let extKey = ext.isEmpty ? "" : "." + ext

            var lines = 0
            var chars = 0

            if let data = try? Data(contentsOf: url) {
                chars = data.count
                if !data.isEmpty {
                    var lineCount = 0
                    for byte in data {
                        if byte == 10 {
                            lineCount += 1
                        }
