                    if let lastByte = data.last, lastByte == 10 {
                        lines = lineCount
                    } else {
                        lines = lineCount + 1
                    }
                }
            }

            let info = FileInfo(relativePath: relativePath, lines: lines, chars: chars)
            files[extKey, default: []].append(info)
        }
    }
}

