#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 4096
#define MAX_NAME 256
#define MAX_DEPT 128

typedef struct {
    char name[MAX_NAME];
    char department[MAX_DEPT];
    double salary;
} Employee;

typedef struct {
    char name[MAX_DEPT];
    double sum;
    int count;
} DeptInfo;

static int cmp_dept(const void *a, const void *b) {
    const DeptInfo *da = (const DeptInfo *)a;
    const DeptInfo *db = (const DeptInfo *)b;
    return strcmp(da->name, db->name);
}

static void format_comma_long(long long val, char *buf, int size) {
    char tmp[32];
    int len;
    if (val < 0) {
        buf[0] = '-';
        len = snprintf(tmp, sizeof(tmp), "%lld", -val);
    } else {
        len = snprintf(tmp, sizeof(tmp), "%lld", val);
    }
    int pos = 0;
    int count = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) {
            buf[pos++] = ',';
        }
        buf[pos++] = tmp[i];
        count++;
    }
    for (int i = 0, j = pos / 2; i < j; i++, j--) {
        char t = buf[i]; buf[i] = buf[j]; buf[j] = t;
    }
    buf[pos] = '\0';
}

static void format_comma_double(double val, char *buf, int size) {
    long long cents = (long long)lround(val * 100.0);
    long long intpart = cents / 100;
    int decpart = (int)(cents % 100);
    if (decpart < 0) decpart = -decpart;
    char intbuf[32];
    format_comma_long(intpart, intbuf, sizeof(intbuf));
    snprintf(buf, size, "%s.%02d", intbuf, decpart);
}

int main(void) {
    const char *path = "<tmp>";

    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        return 1;
    }

    Employee *emps = NULL;
    int n_emps = 0;
    int cap = 0;

    char line[MAX_LINE];
    int first = 1;

    while (fgets(line, sizeof(line), f)) {
        if (first) { first = 0; continue; }

        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;

        char *fields[8] = {0};
        int nf = 0;
        char *p = line;
        while (1) {
            fields[nf++] = p;
            p = strchr(p, ',');
            if (!p) break;
            *p = '\0';
            p++;
        }

        if (nf < 4) continue;

        if (n_emps == cap) {
            cap = cap ? cap * 2 : 64;
            emps = realloc(emps, cap * sizeof(Employee));
            if (!emps) {
                fprintf(stderr, "OOM\n");
                fclose(f);
                return 1;
            }
        }

        strncpy(emps[n_emps].name, fields[1], MAX_NAME - 1);
        emps[n_emps].name[MAX_NAME - 1] = '\0';
        strncpy(emps[n_emps].department, fields[2], MAX_DEPT - 1);
        emps[n_emps].department[MAX_DEPT - 1] = '\0';
        emps[n_emps].salary = atof(fields[3]);
        n_emps++;
    }
    fclose(f);

    DeptInfo *depts = NULL;
    int n_depts = 0;
    int dcap = 0;

    for (int i = 0; i < n_emps; i++) {
        int found = -1;
        for (int j = 0; j < n_depts; j++) {
            if (strcmp(depts[j].name, emps[i].department) == 0) {
                found = j;
                break;
            }
        }
        if (found >= 0) {
            depts[found].sum += emps[i].salary;
            depts[found].count++;
        } else {
            if (n_depts == dcap) {
                dcap = dcap ? dcap * 2 : 32;
                depts = realloc(depts, dcap * sizeof(DeptInfo));
                if (!depts) {
                    fprintf(stderr, "OOM\n");
                    return 1;
                }
            }
            strncpy(depts[n_depts].name, emps[i].department, MAX_DEPT - 1);
            depts[n_depts].name[MAX_DEPT - 1] = '\0';
            depts[n_depts].sum = emps[i].salary;
            depts[n_depts].count = 1;
            n_depts++;
        }
    }

    qsort(depts, n_depts, sizeof(DeptInfo), cmp_dept);

    int hi_idx = 0;
    for (int i = 1; i < n_emps; i++) {
        if (emps[i].salary > emps[hi_idx].salary) {
            hi_idx = i;
        }
    }

    double total = 0.0;
    for (int i = 0; i < n_emps; i++) {
        total += emps[i].salary;
    }

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < n_depts; i++) {
        char buf[64];
        format_comma_double(depts[i].sum / depts[i].count, buf, sizeof(buf));
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    char buf2[64];
    format_comma_long((long long)lround(emps[hi_idx].salary), buf2, sizeof(buf2));
    printf("Highest Paid: %s ($%s)\n", emps[hi_idx].name, buf2);
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < n_depts; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
