    if (l->size == l->cap) {
        l->cap *= 2;
        l->items = (char **)realloc(l->items, sizeof(char *) * (size_t)l->cap);
    }
    l->items[l->size] = strdup(s);
    l->size++;
}

int cmp_namecount(const void *a, const void *b) {
    return strcmp(((const NameCount *)a)->name, ((const NameCount *)b)->name);
}

int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

int main(void) {
    const char *path = "<tmp>";

    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    NameCountList levels;
    nc_init(&levels);

    NameCountList error_components;
    nc_init(&error_components);

    StrList error_msgs;
    sl_init(&error_msgs);

    int hours[24] = {0};

    char *line = NULL;
    size_t linecap = 0;
    ssize_t len;

    while ((len = getline(&line, &linecap, f)) != -1) {
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }
        if (len < 21) continue;

        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        int hour = 0;
        if (line[12] >= '0' && line[12] <= '9' && line[13] >= '0' && line[13] <= '9') {
            hour = (line[12] - '0') * 10 + (line[13] - '0');
        }
        if (hour >= 0 && hour < 24) {
            hours[hour]++;
        }

        char *p = close_bracket + 1;
        if (*p == ' ') p++;

        /* Extract level */
        char *level_start = p;
        while (*p && *p != ' ') p++;
        if (*p == '\0') continue;
        char saved = *p;
        *p = '\0';
        char *level = level_start;
        nc_add(&levels, level);
        *p = saved;

        p++;
        if (*p == '(') p++;
        else continue;

        /* Extract component */
        char *comp_start = p;
        while (*p && *p != ')') p++;
        if (*p != ')') continue;
        saved = *p;
        *p = '\0';
        char *component = comp_start;
        if (strcmp(level, "ERROR") == 0) {
            nc_add(&error_components, component);
        }
        *p = saved;

        p++;
        if (*p == ' ') p++;
        if (*p == '-') p++;
        if (*p == ' ') p++;

        char *message = p;

        if (strcmp(level, "ERROR") == 0) {
            sl_add_unique(&error_msgs, message);
        }
    }

    fclose(f);
    free(line);

    qsort(levels.items, (size_t)levels.size, sizeof(NameCount), cmp_namecount);
    qsort(error_msgs.items, (size_t)error_msgs.size, sizeof(char *), cmp_str);

    int best_comp_idx = -1;
    int best_count = 0;
    for (int i = 0; i < error_components.size; i++) {
        if (error_components.items[i].count > best_count) {
            best_count = error_components.items[i].count;
            best_comp_idx = i;
        }
    }

    int busiest_hour = 0;
    int busiest_count = 0;
    for (int i = 0; i < 24; i++) {
        if (hours[i] > busiest_count) {
            busiest_count = hours[i];
            busiest_hour = i;
        }
    }

    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < levels.size; i++) {
        printf("  %s: %d\n", levels.items[i].name, levels.items[i].count);
    }
    printf("\n");
    if (best_comp_idx >= 0) {
        printf("Component with Most Errors: %s (%d errors)\n",
               error_components.items[best_comp_idx].name, best_count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < error_msgs.size; i++) {
        printf("  - %s\n", error_msgs.items[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest_hour, busiest_count);

    for (int i = 0; i < levels.size; i++) free(levels.items[i].name);
    free(levels.items);
    for (int i = 0; i < error_components.size; i++) free(error_components.items[i].name);
    free(error_components.items);
    for (int i = 0; i < error_msgs.size; i++) free(error_msgs.items[i]);
    free(error_msgs.items);

    return 0;
}
