#include <string.h>
#include <ftw.h>
#include <sys/stat.h>
#include <errno.h>

#define BASE_DIR "<tmp>"
#define BASE_PREFIX_LEN (sizeof(BASE_DIR) - 1)

typedef struct {
    char *relpath;
    char *ext;
    long long lines;
    long long chars;
} FileEntry;

static FileEntry *files = NULL;
static int file_count = 0;
static int file_cap = 0;

static void add_file(const char *fullpath, long long lines, long long chars) {
    if (file_count >= file_cap) {
        file_cap = file_cap ? file_cap * 2 : 128;
        files = (FileEntry *)realloc(files, (size_t)file_cap * sizeof(FileEntry));
        if (!files) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    const char *rel = fullpath + BASE_PREFIX_LEN + 1;
    files[file_count].relpath = strdup(rel);
    if (!files[file_count].relpath) { fprintf(stderr, "OOM\n"); exit(1); }

    const char *dot = strrchr(rel, '.');
    if (dot && dot != rel && dot[1] != '\0') {
        files[file_count].ext = strdup(dot);
    } else {
        files[file_count].ext = strdup("(no extension)");
    }
    if (!files[file_count].ext) { fprintf(stderr, "OOM\n"); exit(1); }

    files[file_count].lines = lines;
    files[file_count].chars = chars;
    file_count++;
}

static int walk_cb(const char *path, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    if (typeflag == FTW_F) {
        long long lines = 0, chars = 0;
        FILE *f = fopen(path, "rb");
        if (f) {
            size_t buf_size = 65536;
            char *buf = (char *)malloc(buf_size);
            if (buf) {
                size_t n;
                while ((n = fread(buf, 1, buf_size, f)) > 0) {
                    chars += (long long)n;
                    for (size_t i = 0; i < n; i++) {
                        if (buf[i] == '\n') lines++;
                    }
                }
                free(buf);
            }
            fclose(f);
        }
        add_file(path, lines, chars);
    }
    return 0;
}

static int cmp_file(const void *a, const void *b) {
    const FileEntry *fa = (const FileEntry *)a;
    const FileEntry *fb = (const FileEntry *)b;
    int c = strcmp(fa->ext, fb->ext);
    if (c != 0) return c;
    return strcmp(fa->relpath, fb->relpath);
}

int main(void) {
    int rc = nftw(BASE_DIR, walk_cb, 256, FTW_PHYS);
    if (rc != 0) {
        fprintf(stderr, "nftw failed: %s\n", strerror(errno));
        return 1;
    }

    if (file_count > 1) {
        qsort(files, (size_t)file_count, sizeof(FileEntry), cmp_file);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long long total_files = 0, total_lines = 0, total_chars = 0;

    int i = 0;
    while (i < file_count) {
        int j = i;
        while (j < file_count && strcmp(files[j].ext, files[i].ext) == 0) j++;

        long long g_lines = 0, g_chars = 0;
        for (int k = i; k < j; k++) {
            g_lines += files[k].lines;
            g_chars += files[k].chars;
        }

        printf("Extension: %s\n", files[i].ext);
        printf("  Files: %lld\n", (long long)(j - i));
        printf("  Total Lines: %lld\n", g_lines);
        printf("  Total Characters: %lld\n", g_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %lld lines, %lld chars\n", files[k].relpath, files[k].lines, files[k].chars);
        }

        total_files += (long long)(j - i);
        total_lines += g_lines;
        total_chars += g_chars;

        i = j;
    }

    printf("\n");
    printf("Total: %lld files, %lld lines, %lld characters\n", total_files, total_lines, total_chars);

    for (int k = 0; k < file_count; k++) {
        free(files[k].relpath);
        free(files[k].ext);
    }
    free(files);

    return 0;
}

