use std::fs;
use std::collections::HashMap;

struct Parser<'a> {
    s: &'a str,
    pos: usize,
}

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { s, pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.s.len() && (self.s.as_bytes()[self.pos] as char).is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.s.as_bytes().get(self.pos).copied()
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some(b'{') => Json::Object(self.parse_object()),
            Some(b'[') => Json::Array(self.parse_array()),
            Some(b'"') => Json::String(self.parse_string()),
            Some(b't') => { self.pos += 4; Json::Bool(true) }
            Some(b'f') => { self.pos += 5; Json::Bool(false) }
            Some(b'n') => { self.pos += 4; Json::Null }
            _ => Json::Number(self.parse_number()),
        }
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let mut result = String::new();
        loop {
            if self.pos >= self.s.len() { break; }
            let c = self.s.as_bytes()[self.pos];
            if c == b'"' {
                self.pos += 1;
                break;
            } else if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.s.len() { break; }
                let esc = self.s.as_bytes()[self.pos];
                match esc {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'n' => result.push('\n'),
                    b't' => result.push('\t'),
                    b'r' => result.push('\r'),
                    b'b' => result.push('\x08'),
                    b'f' => result.push('\x0c'),
                    b'u' => {
                        let hex = &self.s[self.pos + 1..self.pos + 5];
                        let code = u32::from_str_radix(hex, 16).unwrap_or(0xFFFD);
                        result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        self.pos += 4;
                    }
                    _ => result.push(esc as char),
                }
                self.pos += 1;
            } else {
                let len = if c < 0x80 { 1 }
                    else if c < 0xE0 { 2 }
                    else if c < 0xF0 { 3 }
                    else { 4 };
                let end = (self.pos + len).min(self.s.len());
                result.push_str(&self.s[self.pos..end]);
                self.pos += len;
            }
        }
        result
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.s.len() {
            let c = self.s.as_bytes()[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.s[start..self.pos].parse::<f64>().unwrap()
    }

    fn parse_array(&mut self) -> Vec<Json> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return items;
        }
        loop {
            items.push(self.parse_value());
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => break,
            }
        }
        items
    }

    fn parse_object(&mut self) -> Vec<(String, Json)> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return items;
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.pos += 1;
            let val = self.parse_value();
            items.push((key, val));
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => break,
            }
        }
        items
    }
}

struct MinHeap {
    data: Vec<(f64, String)>,
}

impl MinHeap {
    fn new() -> Self {
        MinHeap { data: Vec::new() }
    }

    fn push(&mut self, item: (f64, String)) {
        self.data.push(item);
        let mut i = self.data.len() - 1;
        while i > 0 {
            let parent = (i - 1) / 2;
            if self.data[parent].0 <= self.data[i].0 {
                break;
            }
            self.data.swap(parent, i);
            i = parent;
        }
    }

    fn pop(&mut self) -> Option<(f64, String)> {
        if self.data.is_empty() {
            return None;
        }
        let top = self.data[0].clone();
        let last = self.data.pop().unwrap();
        if !self.data.is_empty() {
            self.data[0] = last;
            let mut i = 0;
            loop {
                let mut smallest = i;
                let left = 2 * i + 1;
                let right = 2 * i + 2;
                if left < self.data.len() && self.data[left].0 < self.data[smallest].0 {
                    smallest = left;
                }
                if right < self.data.len() && self.data[right].0 < self.data[smallest].0 {
                    smallest = right;
                }
                if smallest == i {
                    break;
                }
                self.data.swap(i, smallest);
                i = smallest;
            }
        }
        Some(top)
    }

    fn is_empty(&self) -> bool {
        self.data.is_empty()
    }
}

fn format_distance(d: f64) -> String {
    if (d - d.round()).abs() < 1e-9 {
        format!("{}", d.round() as i64)
    } else {
        format!("{}", d)
    }
}

