    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let (nodes, edges) = match &json {
        Json::Object(fields) => {
            let mut nodes = Vec::new();
            let mut edges = Vec::new();
            for (key, val) in fields {
                if key == "nodes" {
                    if let Json::Array(arr) = val {
                        for item in arr {
                            if let Json::String(s) = item {
                                nodes.push(s.clone());
                            }
                        }
                    }
                } else if key == "edges" {
                    if let Json::Array(arr) = val {
                        for item in arr {
                            if let Json::Object(e) = item {
                                let from = e.iter().find(|(k, _)| k == "from")
                                    .and_then(|(_, v)| if let Json::String(s) = v { Some(s.clone()) } else { None })
                                    .unwrap();
                                let to = e.iter().find(|(k, _) | k == "to")
                                    .and_then(|(_, v)| if let Json::String(s) = v { Some(s.clone()) } else { None })
                                    .unwrap();
                                let weight = e.iter().find(|(k, _) | k == "weight")
                                    .and_then(|(_, v)| if let Json::Number(n) = v { Some(*n) } else { None })
                                    .unwrap();
                                edges.push((from, to, weight));
                            }
                        }
                    }
                }
            }
            (nodes, edges)
        }
        _ => panic!("Invalid JSON structure"),
    };

    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), *weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), *weight));
    }

    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    let mut heap = MinHeap::new();
    heap.push((0.0, source.clone()));

    while let Some((d, node)) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(f64::INFINITY) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                if new_dist < dist.get(neighbor).copied().unwrap_or(f64::INFINITY) {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push((new_dist, neighbor.clone()));
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let d = dist.get(node).copied().unwrap_or(f64::INFINITY);
        let dist_str = if d == f64::INFINITY {
            "unreachable".to_string()
        } else {
            format_distance(d)
        };
        println!("A -> {}: {}", node, dist_str);
    }
