use std::io::{Read, Write};
use std::net::TcpStream;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len()
            && matches!(self.data[self.pos], ' ' | '\t' | '\n' | '\r')
        {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next(), Some(c));
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('"') => Json::Str(self.parse_string()),
            Some('[') => self.parse_array(),
            Some('{') => self.parse_object(),
            Some('t') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some('f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some('n') => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.next().unwrap();
                            code = code * 16 + (c as u32).to_digit(16).unwrap();
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => {}
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.data[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap_or(0.0))
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Json::Array(arr)
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(obj)
    }
}

fn get_field(obj: &[(String, Json)], key: &str) -> Option<&Json> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn decode_chunked(data: &str) -> String {
    let chars: Vec<char> = data.chars().collect();
    let len = chars.len();
    let mut result = String::new();
    let mut pos = 0;

    loop {
        let mut line_end = pos;
        while line_end < len && chars[line_end] != '\n' {
            line_end += 1;
        }
        if line_end >= len {
            break;
        }

        let mut size_str: String = chars[pos..line_end].iter().collect();
        if size_str.ends_with('\r') {
            size_str.pop();
        }
        if let Some(semi) = size_str.find(';') {
            size_str.truncate(semi);
        }

        let size: usize = usize::from_str_radix(size_str.trim(), 16).unwrap_or(0);
        pos = line_end + 1;

        if size == 0 {
            break;
        }

        let chunk_end = (pos + size).min(len);
        result.push_str(&chars[pos..chunk_end].iter().collect::<String>());
        pos = chunk_end;
        if pos < len && chars[pos] == '\r' {
            pos += 1;
        }
        if pos < len && chars[pos] == '\n' {
            pos += 1;
        }
    }

    result
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");
    let request =
        "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream
        .write_all(request.as_bytes())
        .expect("Failed to write");

    let mut response = Vec::new();
    let mut buf = [0u8; 4096];
    loop {
        match stream.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => response.extend_from_slice(&buf[..n]),
            Err(_) => break,
        }
    }

    let response_str = String::from_utf8(response).expect("Invalid UTF-8");
    let header_end = response_str.find("\r\n\r\n").unwrap_or(0);
    let headers = &response_str[..header_end];
    let body_raw = &response_str[header_end + 4..];

    let body = if headers.to_lowercase().contains("transfer-encoding: chunked") {
        decode_chunked(body_raw)
    } else {
        body_raw.to_string()
    };

    let mut parser = Parser::new(&body);
    let json = parser.parse_value();

    let products = match &json {
        Json::Array(arr) => arr,
        _ => panic!("Expected JSON array"),
    };

    let mut filtered: Vec<(String, f64)> = Vec::new();
    for item in products {
        if let Json::Object(obj) = item {
            let name = get_field(obj, "name")
                .and_then(|v| {
                    if let Json::Str(s) = v {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .unwrap_or_default();
            let price = get_field(obj, "price")
                .and_then(|v| {
                    if let Json::Number(n) = v {
                        Some(*n)
                    } else {
                        None
                    }
                })
                .unwrap_or(0.0);
            if price > 50.00 {
                filtered.push((name, price));
            }
        }
    }

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}

