typedef struct {
    int id;
    char *name;
    double price;
    char *category;
    int stock;
} Product;

static const char *skip_ws(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static char *parse_json_string(const char **pos) {
    const char *p = skip_ws(*pos);
    if (*p != '"') return NULL;
    p++;
    const char *start = p;
    while (*p && *p != '"') {
        if (*p == '\\' && p[1]) p++;
        p++;
    }
    if (*p != '"') return NULL;
    size_t len = (size_t)(p - start);
    char *result = malloc(len + 1);
    if (!result) return NULL;
    memcpy(result, start, len);
    result[len] = '\0';
    *pos = p + 1;
    return result;
}

static double parse_json_number(const char **pos) {
    const char *p = skip_ws(*pos);
    char *end;
    double val = strtod(p, &end);
    *pos = end;
    return val;
}

static int parse_product(const char **pos, Product *prod) {
    const char *p = skip_ws(*pos);
    if (*p != '{') return 0;
    p++;

    prod->id = 0;
    prod->name = NULL;
    prod->price = 0.0;
    prod->category = NULL;
    prod->stock = 0;

    while (1) {
        p = skip_ws(p);
        if (*p == '}') { p++; *pos = p; return 1; }
        if (*p != '"') return 0;

        char *key = parse_json_string(&p);
        if (!key) return 0;

        p = skip_ws(p);
        if (*p != ':') { free(key); return 0; }
        p++;

        p = skip_ws(p);

        if (strcmp(key, "id") == 0) {
            prod->id = (int)parse_json_number(&p);
        } else if (strcmp(key, "name") == 0) {
            prod->name = parse_json_string(&p);
        } else if (strcmp(key, "price") == 0) {
            prod->price = parse_json_number(&p);
        } else if (strcmp(key, "category") == 0) {
            prod->category = parse_json_string(&p);
        } else if (strcmp(key, "stock") == 0) {
            prod->stock = (int)parse_json_number(&p);
        } else {
            if (*p == '"') {
                parse_json_string(&p);
            } else if (*p == '{' || *p == '[') {
                int depth = 0;
                while (*p) {
                    if (*p == '"') {
                        p++;
                        while (*p && *p != '"') { if (*p == '\\' && p[1]) p++; p++; }
                    } else if (*p == '{' || *p == '[') {
                        depth++;
                    } else if (*p == '}' || *p == ']') {
                        depth--;
                        if (depth == 0) { p++; break; }
                    }
                    p++;
                }
            } else {
                if (*p == 't' || *p == 'f' || *p == 'n') {
                    while (*p && *p != ',' && *p != '}' && *p != ']' &&
                           *p != ' ' && *p != '\t' && *p != '\r' && *p != '\n') p++;
                } else {
                    parse_json_number(&p);
                }
            }
        }

        free(key);

        p = skip_ws(p);
        if (*p == ',') { p++; continue; }
        if (*p == '}') { p++; *pos = p; return 1; }
        return 0;
    }
}

static int compare_products(const void *a, const void *b) {
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;
    if (!pa->name && !pb->name) return 0;
    if (!pa->name) return 1;
    if (!pb->name) return -1;
    return strcmp(pa->name, pb->name);
}

static char *http_get(const char *host, int port, const char *path) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return NULL;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((unsigned short)port);
    addr.sin_addr.s_addr = inet_addr(host);

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        return NULL;
    }

    char request[512];
    int rlen = snprintf(request, sizeof(request),
        "GET %s HTTP/1.1\r\nHost: %s:%d\r\nConnection: close\r\n\r\n",
        path, host, port);

    if (send(sock, request, (size_t)rlen, 0) < 0) {
        close(sock);
        return NULL;
    }

    size_t buf_size = 65536;
    char *buf = malloc(buf_size);
    if (!buf) { close(sock); return NULL; }

    size_t total = 0;
    for (;;) {
        if (total + 8192 > buf_size) {
            buf_size *= 2;
            char *tmp = realloc(buf, buf_size);
            if (!tmp) { free(buf); close(sock); return NULL; }
            buf = tmp;
        }
        ssize_t n = recv(sock, buf + total, buf_size - total, 0);
        if (n <= 0) break;
        total += (size_t)n;
    }
    close(sock);

    buf[total] = '\0';

    char *body = strstr(buf, "\r\n\r\n");
    if (body) {
        body += 4;
    } else {
        body = strstr(buf, "\n\n");
        if (body) body += 2;
        else body = buf;
    }

    char *bp = body;
    while (*bp == ' ' || *bp == '\t' || *bp == '\r' || *bp == '\n') bp++;
    int is_chunked = 0;
    if ((*bp >= '0' && *bp <= '9') || (*bp >= 'a' && *bp <= 'f') ||
        (*bp >= 'A' && *bp <= 'F')) {
        char *q = bp;
        while ((*q >= '0' && *q <= '9') || (*q >= 'a' && *q <= 'f') ||
               (*q >= 'A' && *q <= 'F')) q++;
        if (*q == '\r' || *q == '\n') is_chunked = 1;
    }

    if (is_chunked) {
        size_t max_dec = total;
        char *decoded = malloc(max_dec + 1);
        if (!decoded) { free(buf); return NULL; }
        size_t dlen = 0;
        char *cp = bp;
        while (*cp) {
            unsigned long csize = 0;
            while ((*cp >= '0' && *cp <= '9') || (*cp >= 'a' && *cp <= 'f') ||
                   (*cp >= 'A' && *cp <= 'F')) {
                if (*cp >= '0' && *cp <= '9') csize = csize * 16 + (unsigned long)(*cp - '0');
                else if (*cp >= 'a' && *cp <= 'f') csize = csize * 16 + (unsigned long)(*cp - 'a' + 10);
                else csize = csize * 16 + (unsigned long)(*cp - 'A' + 10);
                cp++;
            }
            while (*cp == '\r' || *cp == '\n') cp++;
            if (csize == 0) break;
            if (dlen + csize >= max_dec) { free(decoded); free(buf); return NULL; }
            memcpy(decoded + dlen, cp, csize);
            dlen += csize;
            cp += csize;
            while (*cp == '\r' || *cp == '\n') cp++;
        }
        decoded[dlen] = '\0';
        free(buf);
        return decoded;
    }

    size_t body_len = strlen(body);
    char *result = malloc(body_len + 1);
    if (!result) { free(buf); return NULL; }
    memcpy(result, body, body_len);
    result[body_len] = '\0';
    free(buf);
    return result;
}

int main(void) {
    char *body = http_get("127.0.0.1", 18923, "/api/products");

    Product *products = malloc((size_t)MAX_PRODUCTS * sizeof(Product));
    if (!products) return 1;
    int count = 0;

    if (body) {
        const char *pos = body;
        pos = skip_ws(pos);
        if (*pos == '[') {
            pos++;
            for (;;) {
                pos = skip_ws(pos);
                if (*pos == ']') { pos++; break; }
                if (*pos != '{') break;
                if (count < MAX_PRODUCTS) {
                    if (parse_product(&pos, &products[count])) {
                        count++;
                    }
                } else {
                    break;
                }
                pos = skip_ws(pos);
                if (*pos == ',') { pos++; continue; }
                if (*pos == ']') { pos++; break; }
                break;
            }
        }
        free(body);
    }

    /* Filter: price > 50.00 */
    int filtered_count = 0;
    double total_price = 0.0;
    for (int i = 0; i < count; i++) {
        if (products[i].price > 50.00) {
            products[filtered_count] = products[i];
            filtered_count++;
            total_price += products[i].price;
        }
    }

    /* Sort by name ascending */
    qsort(products, (size_t)filtered_count, sizeof(Product), compare_products);

    /* Output */
    printf("=== Filtered Products (price > $50.00) ===\n");
    printf("\n");
    for (int i = 0; i < filtered_count; i++) {
        printf("%s: $%.2f\n", products[i].name ? products[i].name : "", products[i].price);
    }
    printf("\n");
    printf("Count: %d\n", filtered_count);
    printf("Total: $%.2f\n", total_price);

    for (int i = 0; i < filtered_count; i++) {
        free(products[i].name);
        free(products[i].category);
    }
    free(products);

    return 0;
}
